import Foundation

enum ExpandedCatalog {
    private struct Seed {
        let id: String
        let title: String
        let subtitle: String
        let subject: CourseSubject
        let level: CourseLevel
        let symbol: String
        let minutes: Int
        let lessonTitle: String
        let summary: String
        let overview: String
        let keyIdeas: [String]
        let noteTitle: String
        let noteBody: String
        let sourceTitle: String
        let provider: String
        let url: String
        let license: String
        let prompt: String
        let answers: [String]
        let correct: Int
        let explanation: String
    }

    static func content(accessedOn: Date) -> LearningContent {
        let seeds = highSchoolSeeds + collegeSeeds
        let courses = seeds.map { seed -> Course in
            let source = reference(for: seed, accessedOn: accessedOn)
            let curriculum = CurriculumReference(
                title: seed.sourceTitle,
                provider: seed.provider,
                url: source.url,
                license: seed.license,
                attribution: "Original foundation lesson aligned to (seed.sourceTitle)."
            )
            return Course(
                id: seed.id,
                title: seed.title,
                subtitle: seed.subtitle,
                subject: seed.subject,
                level: seed.level,
                symbolName: seed.symbol,
                estimatedMinutes: seed.minutes,
                objectiveIDs: ["\(seed.id)-foundation"],
                source: source,
                curriculum: curriculum
            )
        }
        let objectives = seeds.map { seed in
            LearningObjective(
                id: "\(seed.id)-foundation",
                title: seed.lessonTitle,
                summary: seed.summary,
                order: 0,
                prerequisiteIDs: [],
                source: reference(for: seed, accessedOn: accessedOn)
            )
        }
        let questions = seeds.flatMap { seed -> [PracticeQuestion] in
            let source = reference(for: seed, accessedOn: accessedOn)
            let objectiveID = "\(seed.id)-foundation"
            let ids = ["a", "b", "c", "d"]
            let firstChoices = zip(ids, seed.answers).map { AnswerChoice(id: $0.0, text: $0.1) }
            let keyIdeaChoices = [
                AnswerChoice(id: "a", text: seed.keyIdeas[0]),
                AnswerChoice(id: "b", text: "A conclusion is reliable even when its steps cannot be checked."),
                AnswerChoice(id: "c", text: "The same rule produces the correct result in every unrelated situation."),
                AnswerChoice(id: "d", text: "Evidence and definitions are optional when an answer sounds reasonable.")
            ]
            return [
                PracticeQuestion(id: "\(seed.id)-check", objectiveID: objectiveID, prompt: seed.prompt, choices: firstChoices, correctChoiceID: ids[seed.correct], explanation: seed.explanation, source: source),
                PracticeQuestion(id: "\(seed.id)-idea", objectiveID: objectiveID, prompt: "Which idea belongs in a strong summary of this lesson?", choices: keyIdeaChoices, correctChoiceID: "a", explanation: "A strong summary preserves the central idea: \(seed.keyIdeas[0])", source: source)
            ]
        }
        let lessons = seeds.map { seed in
            LessonMaterial(
                objectiveID: "\(seed.id)-foundation",
                overview: seed.overview,
                keyIdeas: seed.keyIdeas,
                notes: [NoteSection(title: seed.noteTitle, body: seed.noteBody)],
                video: nil,
                readingURL: URL(string: seed.url)!,
                attribution: "Original notes aligned to \(seed.sourceTitle) from \(seed.provider)."
            )
        }
        return LearningContent(courses: courses, objectives: objectives, questions: questions, lessonMaterials: lessons)
    }

    private static func reference(for seed: Seed, accessedOn: Date) -> SourceReference {
        SourceReference(title: seed.sourceTitle, publisher: seed.provider, url: URL(string: seed.url)!, accessedOn: accessedOn)
    }

